using System.Net;
using System.Text.Json;
using Htt.Host.Api.MasterData;
using Htt.Host.Api.Inventory;
using Htt.Host.Api.Sales;
using Htt.Infrastructure;
using Htt.Infrastructure.Documents;
using Npgsql;
using Xunit;
using static Htt.IntegrationTests.SalesFlowSupport;
namespace Htt.IntegrationTests;
public sealed class WarehouseDetailTests:IAsyncLifetime
{
    private static Task<JsonElement> VerifiedGet(HttpClient c,string path)=>ReadVerified(c,path);
    private static async Task<JsonElement> ReadVerified(HttpClient c,string path)=>await Expect(await c.GetAsync("/api/v1"+path),HttpStatusCode.OK);
    private readonly DatabaseFixture db=new();
    public Task InitializeAsync()=>db.InitializeAsync();public Task DisposeAsync()=>db.DisposeAsync();
    private Task<object?> S(string sql,params(string,object)[]args)=>db.OwnerScalarAsync(sql,args);
    private async Task<SalesData> Stock(HttpClient c){var d=await Setup(db,c,22);await StockValuation.InitializeAsync(db.Owner,db.Company,d.Warehouse,d.Product,1000,"Warehouse count opening",DatabaseFixture.Issuer,db.Subject);return d;}
    private static async Task<JsonElement[]> Positions(HttpClient c,SalesData d)=>(await VerifiedGet(c,$"/warehouse/positions?warehouseId={d.Warehouse}&productId={d.Product}")).GetProperty("items").EnumerateArray().ToArray();
    private static async Task Consistent(HttpClient c){var result=await VerifiedGet(c,"/accounting/reconciliation");Assert.Equal("CONSISTENT",result.GetProperty("status").GetString());}
    [Fact]
    public async Task Unassigned_stock_can_be_split_into_bins_and_batches_without_financial_movement()
    {
        await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);var source=(await Positions(c,d)).Single(x=>D(x.GetProperty("quantity"))>0);Assert.Equal("UNASSIGNED",source.GetProperty("binCode").GetString());var bin=await Expect(await Send(c,HttpMethod.Post,"/warehouse/bins",new BinInput(d.Warehouse,"A01","Shelf A01")),HttpStatusCode.Created);await Expect(await Send(c,HttpMethod.Post,"/warehouse/location-moves",new PositionMoveInput(source.GetProperty("id").GetGuid(),bin.GetProperty("id").GetGuid(),"BATCH-1",10,Code(),"Counted physical stock")),HttpStatusCode.Created);var positions=await Positions(c,d);Assert.Equal(22,positions.Sum(x=>D(x.GetProperty("quantity"))));Assert.Equal(10,D(positions.Single(x=>x.GetProperty("lotCode").GetString()=="BATCH-1").GetProperty("quantity")));Assert.Equal(1000m,await S("SELECT sum(value) FROM inventory.stock_values WHERE company_id=@company",("company",db.Company)));await Consistent(c);
    }
    [Theory]
    [InlineData(true)][InlineData(false)]
    public async Task Explicit_bin_picking_consumes_selected_batch_and_cancel_releases_location_reservation(bool dispatch)
    {
        await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);var source=(await Positions(c,d)).Single(x=>D(x.GetProperty("quantity"))>0);var bin=await Expect(await Send(c,HttpMethod.Post,"/warehouse/bins",new BinInput(d.Warehouse,"A01","Shelf A01")),HttpStatusCode.Created);await Expect(await Send(c,HttpMethod.Post,"/warehouse/location-moves",new PositionMoveInput(source.GetProperty("id").GetGuid(),bin.GetProperty("id").GetGuid(),"BATCH-1",10,Code(),"Counted stock")),HttpStatusCode.Created);var pos=(await Positions(c,d)).Single(x=>x.GetProperty("lotCode").GetString()=="BATCH-1");var q=await Submitted(c,d.Draft(2));var order=(await Expect(await Approve(c,q.Id,q.Version),HttpStatusCode.Created)).GetProperty("orderId").GetGuid();var o=await VerifiedGet(c,$"/sales-orders/{order}");var line=o.GetProperty("lines")[0].GetProperty("id").GetGuid();var bqty=D(o.GetProperty("lines")[0].GetProperty("baseQuantity"))/2;var pick=await Expect(await Send(c,HttpMethod.Post,$"/warehouse/orders/{order}/picks",new PickInput([new(line,1,"Remaining cartons damaged",[new(pos.GetProperty("id").GetGuid(),bqty)])]),1),HttpStatusCode.Created);Assert.Single(pick.GetProperty("positions").EnumerateArray());Assert.Single(pick.GetProperty("shortages").EnumerateArray());Assert.Equal(bqty,D((await Positions(c,d)).Single(x=>x.GetProperty("id").GetGuid()==pos.GetProperty("id").GetGuid()).GetProperty("pickedReserved")));await Expect(await Send(c,HttpMethod.Post,$"/warehouse/picks/{pick.GetProperty("id").GetGuid()}/"+(dispatch?"confirm":"cancel"),dispatch?new DispatchInput("PICKUP","Customer","Docket"):null,1),HttpStatusCode.OK);var after=(await Positions(c,d)).Single(x=>x.GetProperty("id").GetGuid()==pos.GetProperty("id").GetGuid());Assert.Equal(dispatch?10-bqty:10,D(after.GetProperty("quantity")));Assert.Equal(0,D(after.GetProperty("pickedReserved")));await Consistent(c);
    }
    [Fact]
    public async Task Location_moves_are_idempotent_and_concurrent_moves_cannot_overdraw()
    {
        await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);var pos=(await Positions(c,d)).Single(x=>D(x.GetProperty("quantity"))>0);var bin=await Expect(await Send(c,HttpMethod.Post,"/warehouse/bins",new BinInput(d.Warehouse,"A01","Shelf")),HttpStatusCode.Created);var input=new PositionMoveInput(pos.GetProperty("id").GetGuid(),bin.GetProperty("id").GetGuid(),"BATCH",10,Code(),"Verified count");var key=Code();var race=await Task.WhenAll(Send(c,HttpMethod.Post,"/warehouse/location-moves",input,key:key),Send(c,HttpMethod.Post,"/warehouse/location-moves",input,key:key));var a=await Expect(race[0],HttpStatusCode.Created);Assert.True(JsonElement.DeepEquals(a,await Expect(race[1],HttpStatusCode.Created)));var competing=await Task.WhenAll(Send(c,HttpMethod.Post,"/warehouse/location-moves",input with{Reference=Code()}),Send(c,HttpMethod.Post,"/warehouse/location-moves",input with{Reference=Code()}));Assert.Single(competing,x=>x.StatusCode==HttpStatusCode.Created);Assert.Single(competing,x=>x.StatusCode==HttpStatusCode.Conflict);Assert.Equal(22,(await Positions(c,d)).Sum(x=>D(x.GetProperty("quantity"))));await Consistent(c);
    }
    [Fact]
    public async Task Warehouse_scopes_scan_and_occupied_bin_status_are_checked()
    {
        await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);var hidden=await Setup(db,c,0);var staff=await Staff(db,"WAREHOUSE",d);using var wh=api.Authenticated(staff.Subject);await Expect(await wh.GetAsync($"/api/v1/warehouse/positions?warehouseId={hidden.Warehouse}"),HttpStatusCode.Forbidden);var bin=await Expect(await Send(wh,HttpMethod.Post,"/warehouse/bins",new BinInput(d.Warehouse,"A01","Shelf")),HttpStatusCode.Created);Assert.Equal("BIN",(await Expect(await wh.GetAsync($"/api/v1/warehouse/scan?warehouseId={d.Warehouse}&code=BIN:{bin.GetProperty("id").GetGuid()}"),HttpStatusCode.OK)).GetProperty("kind").GetString());var pos=(await Positions(c,d)).Single(x=>D(x.GetProperty("quantity"))>0);await Expect(await Send(wh,HttpMethod.Put,$"/warehouse/bins/{pos.GetProperty("binId").GetGuid()}",new BinUpdateInput("Disabled",false),1),HttpStatusCode.Conflict);await Expect(await Send(wh,HttpMethod.Put,$"/warehouse/bins/{bin.GetProperty("id").GetGuid()}",new BinUpdateInput("Disabled",false),1),HttpStatusCode.OK);Assert.Equal("PRODUCT",(await VerifiedGet(wh,$"/warehouse/scan?warehouseId={d.Warehouse}&code="+(string)(await S("SELECT sku FROM catalog.products WHERE company_id=@company AND id=@id",("company",db.Company),("id",d.Product)))!)).GetProperty("kind").GetString());await Consistent(c);
    }

    [Fact]
    public async Task Legacy_unassigned_requires_current_posted_count_before_allocation()
    {
        await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);var pos=(await Positions(c,d)).Single(x=>D(x.GetProperty("quantity"))>0);await S("ALTER TABLE inventory.position_movements DISABLE TRIGGER append_only;UPDATE inventory.position_movements SET reason='LEGACY_UNASSIGNED_OPENING' WHERE company_id=@company;ALTER TABLE inventory.position_movements ENABLE TRIGGER append_only",("company",db.Company));var bin=await Expect(await Send(c,HttpMethod.Post,"/warehouse/bins",new BinInput(d.Warehouse,"A01","Counted")),HttpStatusCode.Created);var input=new PositionMoveInput(pos.GetProperty("id").GetGuid(),bin.GetProperty("id").GetGuid(),"LEGACY-COUNTED",10,Code(),"Count verified");await Expect(await Send(c,HttpMethod.Post,"/warehouse/location-moves",input),HttpStatusCode.Conflict);var count=await Expect(await Send(c,HttpMethod.Post,"/inventory/stock-counts",new StockCountInput(d.Warehouse,Code(),"Migration allocation",[d.Product])),HttpStatusCode.Created);var id=count.GetProperty("count").GetProperty("id").GetGuid();await Expect(await Send(c,HttpMethod.Post,$"/inventory/stock-counts/{id}/submit",new StockCountSubmission([new(d.Product,22)]),1),HttpStatusCode.OK);await Expect(await Send(c,HttpMethod.Post,$"/inventory/stock-counts/{id}/post",version:2),HttpStatusCode.OK);await Expect(await Send(c,HttpMethod.Post,"/warehouse/location-moves",input with{CountId=id}),HttpStatusCode.Created);await Consistent(c);
    }

    private sealed class CleanPhotoScanner:IFileScanner{public Task<bool> IsCleanAsync(byte[] bytes,CancellationToken ct)=>Task.FromResult(true);}
    private sealed class UnusedRenderer:IPdfRenderer{public Task<byte[]> RenderAsync(JsonElement snapshot,CancellationToken ct)=>throw new InvalidOperationException();}
    private sealed class UnusedMailer:IDocumentMailer{public Task<string> SendAsync(Guid id,JsonElement message,CancellationToken ct)=>throw new InvalidOperationException();}
    [Fact]
    public async Task Pick_handover_photo_uses_private_scanned_attachments_and_warehouse_scope()
    {
        await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);var q=await Submitted(c,d.Draft(1));var order=(await Expect(await Approve(c,q.Id,q.Version),HttpStatusCode.Created)).GetProperty("orderId").GetGuid();var o=await VerifiedGet(c,$"/sales-orders/{order}");var pick=await Expect(await Send(c,HttpMethod.Post,$"/warehouse/orders/{order}/picks",new PickInput([new(o.GetProperty("lines")[0].GetProperty("id").GetGuid(),1)]),1),HttpStatusCode.Created);var id=pick.GetProperty("id").GetGuid();var staff=await Staff(db,"WAREHOUSE",d);using var wh=api.Authenticated(staff.Subject);var other=await Staff(db,"WAREHOUSE");using var outside=api.Authenticated(other.Subject);byte[] photo=[255,216,255,224,1,2,3,255,217];var key=Code();
        async Task<HttpResponseMessage> Upload(HttpClient client){using var request=new HttpRequestMessage(HttpMethod.Post,$"/api/v1/documents/{id}/attachments?fileName=handover.jpg");request.Headers.Add("Idempotency-Key",key);request.Headers.TryAddWithoutValidation("If-Match","\"1\"");request.Content=new ByteArrayContent(photo);request.Content.Headers.ContentType=new("image/jpeg");return await client.SendAsync(request);}
        var file=await Expect(await Upload(wh),HttpStatusCode.Accepted);Assert.True(JsonElement.DeepEquals(file,await Expect(await Upload(wh),HttpStatusCode.Accepted)));var fid=file.GetProperty("id").GetGuid();await Expect(await wh.GetAsync($"/api/v1/files/{fid}/content"),HttpStatusCode.Conflict);await S("UPDATE platform.document_jobs SET available_at=now()-interval '1 day' WHERE company_id=@company AND id=@id",("company",db.Company),("id",file.GetProperty("jobId").GetGuid()));await using var source=NpgsqlDataSource.Create(db.Worker);Assert.True(await new DocumentWorker(source,new UnusedRenderer(),new CleanPhotoScanner(),new UnusedMailer()).ProcessOneAsync());using var content=await wh.GetAsync($"/api/v1/files/{fid}/content");Assert.Equal(HttpStatusCode.OK,content.StatusCode);Assert.Equal(photo,await content.Content.ReadAsByteArrayAsync());var denied=await outside.GetAsync($"/api/v1/files/{fid}/content");Assert.True(denied.StatusCode is HttpStatusCode.Forbidden or HttpStatusCode.NotFound);await Consistent(c);
    }

    [Fact]
    public async Task Multiple_lines_of_one_pick_can_dispatch_the_same_fully_allocated_position()
    {
        await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);var source=(await Positions(c,d)).Single(x=>D(x.GetProperty("quantity"))>0);var bin=await Expect(await Send(c,HttpMethod.Post,"/warehouse/bins",new BinInput(d.Warehouse,"SHARED","Shared bin")),HttpStatusCode.Created);await Expect(await Send(c,HttpMethod.Post,"/warehouse/location-moves",new PositionMoveInput(source.GetProperty("id").GetGuid(),bin.GetProperty("id").GetGuid(),"SHARED",4.4m,Code(),"Counted batch")),HttpStatusCode.Created);var pos=(await Positions(c,d)).Single(x=>x.GetProperty("lotCode").GetString()=="SHARED").GetProperty("id").GetGuid();var q=await Submitted(c,d.Draft(1) with{Lines=[new(d.BoxUnit,Quantity:1),new(d.BoxUnit,Quantity:1)]});var order=(await Expect(await Approve(c,q.Id,q.Version),HttpStatusCode.Created)).GetProperty("orderId").GetGuid();var o=await VerifiedGet(c,$"/sales-orders/{order}");var lines=o.GetProperty("lines").EnumerateArray().Select(x=>new PickLineInput(x.GetProperty("id").GetGuid(),1,Positions:[new(pos,2.2m)])).ToArray();var pick=await Expect(await Send(c,HttpMethod.Post,$"/warehouse/orders/{order}/picks",new PickInput(lines),1),HttpStatusCode.Created);await Expect(await Send(c,HttpMethod.Post,$"/warehouse/picks/{pick.GetProperty("id").GetGuid()}/confirm",new DispatchInput("PICKUP","Customer","Docket"),1),HttpStatusCode.OK);Assert.Equal(0,D((await Positions(c,d)).Single(x=>x.GetProperty("id").GetGuid()==pos).GetProperty("quantity")));await Consistent(c);
    }

    [Fact]
    public async Task Count_proof_is_rechecked_after_waiting_for_the_stock_lock()
    {
        await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);var pos=(await Positions(c,d)).Single(x=>D(x.GetProperty("quantity"))>0);var bin=await Expect(await Send(c,HttpMethod.Post,"/warehouse/bins",new BinInput(d.Warehouse,"LOCKED","Counted bin")),HttpStatusCode.Created);var sheet=await Expect(await Send(c,HttpMethod.Post,"/inventory/stock-counts",new StockCountInput(d.Warehouse,Code(),"Proof race",[d.Product])),HttpStatusCode.Created);var id=sheet.GetProperty("count").GetProperty("id").GetGuid();await Expect(await Send(c,HttpMethod.Post,$"/inventory/stock-counts/{id}/submit",new StockCountSubmission([new(d.Product,22)]),1),HttpStatusCode.OK);await Expect(await Send(c,HttpMethod.Post,$"/inventory/stock-counts/{id}/post",version:2),HttpStatusCode.OK);
        await using var connection=new NpgsqlConnection(db.Owner);await connection.OpenAsync();await using var tx=await connection.BeginTransactionAsync();await using var command=new NpgsqlCommand("SELECT set_config('htt.company_id',@company::text,true);SELECT id FROM inventory.stock_balances WHERE company_id=@company AND warehouse_id=@warehouse AND product_id=@product FOR UPDATE",connection,tx);command.Parameters.AddWithValue("company",db.Company);command.Parameters.AddWithValue("warehouse",d.Warehouse);command.Parameters.AddWithValue("product",d.Product);await command.ExecuteNonQueryAsync();var pending=Send(c,HttpMethod.Post,"/warehouse/location-moves",new PositionMoveInput(pos.GetProperty("id").GetGuid(),bin.GetProperty("id").GetGuid(),"COUNTED",1,Code(),"Current count required",id));
        var blocked=false;for(var attempt=0;attempt<100;attempt++){if(Convert.ToBoolean(await S("SELECT EXISTS(SELECT 1 FROM pg_stat_activity WHERE @pid=ANY(pg_blocking_pids(pid)))",("pid",connection.ProcessID)))){blocked=true;break;}await Task.Delay(50);}Assert.True(blocked,"Location move must be waiting behind the inventory writer.");command.CommandText="UPDATE inventory.stock_balances SET revision=revision+1 WHERE company_id=@company AND warehouse_id=@warehouse AND product_id=@product";await command.ExecuteNonQueryAsync();await tx.CommitAsync();await Expect(await pending,HttpStatusCode.Conflict);Assert.Equal(22,(await Positions(c,d)).Sum(x=>D(x.GetProperty("quantity"))));await Consistent(c);
    }

}
